describe('Login Page', () => {
  beforeEach(() => {
    // assuming the application URL is stored in a variable
    cy.visit(Cypress.env('APPLICATION_URL'));
  });

  it('displays email input field', () => {
    // using data-testid as the preferred selector
    cy.get('[data-testid="email-input"]').should('be.visible');
  });

  it('displays email input field on Firefox', () => {
    // using Firefox browser
    cy.browser('firefox', () => {
      cy.visit(Cypress.env('APPLICATION_URL'));
      cy.get('[data-testid="email-input"]').should('be.visible');
    });
  });

  it('displays email input field with aria-label as fallback', () => {
    // using aria-label as the fallback selector
    cy.get('[aria-label="Email"]').should('be.visible');
  });

  it('displays email input field with visible text as fallback', () => {
    // using visible text as the last fallback selector
    cy.contains('Email').should('be.visible');
  });
});

describe('Password Reset Functionality', () => {
  beforeEach(() => {
    // assuming the application URL is stored in a variable
    cy.visit(Cypress.env('APPLICATION_URL'));
  });

  it('should allow users to reset their password via email', () => {
    // navigate to the login page and click on the forgot password link
    cy.get('[data-testid="login-form"]').within(() => {
      cy.get('[data-testid="forgot-password-link"]').click();
    });

    // enter a valid email address and submit the form
    cy.get('[data-testid="forgot-password-form"]').within(() => {
      cy.get('[data-testid="email-input"]').type('test@example.com');
      cy.get('[data-testid="submit-button"]').click();
    });

    // verify that a reset link is sent to the email
    cy.get('[data-testid="reset-link-sent-message"]').should('be.visible');

    // get the reset link from the email (this might require a custom command or a third-party library)
    cy.getResetLinkFromEmail().then((resetLink) => {
      // visit the reset link
      cy.visit(resetLink);

      // verify that the reset link is still valid after 5 seconds
      cy.wait(5000);
      cy.get('[data-testid="reset-password-form"]').should('be.visible');
    });

    // assert that the reset link expires in more than 5 seconds
    cy.get('[data-testid="reset-link-expiration-message"]').should('contain', 'Link is valid for more than 5 seconds');
  });
});

describe('Login button focusability test', () => {
  beforeEach(() => {
    // assuming the application URL is stored in a variable
    cy.visit('https://example.com/login');
  });

  it('should focus the login button using keyboard navigation on Safari', () => {
    // use data-testid as the preferred selector
    cy.get('[data-testid="login-button"]').should('be.focusable');
    cy.get('[data-testid="login-button"]').focus().should('have.focus');
    cy.get('[data-testid="login-button"]').should('be.clickable');
    cy.get('[data-testid="login-button"]').click().then(() => {
      // assert the expected behavior after clicking the login button
      cy.url().should('contain', '/dashboard');
    });
  });

  it('should handle keyboard navigation on Safari', () => {
    cy.get('body').tab().then(() => {
      cy.get('[data-testid="login-button"]').should('have.focus');
    });
  });
});
